        encoder.resolveQuerySet(this._querySet, 0, slotCount, this._resolveBuffer, 0);
        encoder.copyBufferToBuffer(this._resolveBuffer, 0, staging, 0, byteSize);
        this.frame._staging = staging;
        this.frame._byteSize = byteSize;
